#include <vector>
using namespace std;

class Solution {
public:
    int minOperations(vector<int>& nums) {
        int maxBit = 0, ones = 0;
        for (int num : nums) {
            int b = 0;
            while (num) {
                if (num & 1) ++ones;
                num >>= 1;
                ++b;
            }
            maxBit = max(maxBit, b - 1);
        }
        return ones + maxBit;
    }
};
